create table opposition_worker_private.territorial_reviews (
  source_id uuid not null,
  external_id text not null,
  decision text not null check (decision in (
    'vinculada','seguimiento','provision_o_gestion_interna','antecedente_territorial',
    'programa_previo','bases_territoriales','bases_espera_boe','fuera_de_ambito'
  )),
  prior_reference text,
  publication_type text,
  evidence_note text not null,
  evidence_url text not null,
  official_pdf_url text,
  confirmed_exam_date date,
  reviewed_at timestamptz not null default now(),
  primary key (source_id,external_id),
  foreign key (source_id,external_id) references public.opposition_territorial_inbox(source_id,external_id)
);
revoke all on opposition_worker_private.territorial_reviews from public, anon, authenticated, service_role;

