) v(method,ref,decision,prior,kind,note,url,pdf,exam_date)
join public.opposition_sources s on s.consultation_method=v.method
join public.opposition_territorial_inbox i on i.source_id=s.id and i.external_id=v.ref
on conflict (source_id,external_id) do nothing;

-- The BOE notice explicitly identifies the 40 positions and BOC 233 of 19 November.
update public.opposition_calls c
set official_call_identifier='BOE-A-2026-24883', official_call_identifier_authority='BOE'
from public.opposition_sources s
where c.source_id=s.id and s.consultation_method='boe_sumario_api'
and c.source_external_id='BOE-A-2026-24883' and c.official_call_identifier is null;

update public.opposition_calls c
set vacancies=v.vacancies
from (values
  ('BOE-A-2026-21025',1),('BOE-A-2026-21026',4),('BOE-A-2026-22763',1),
  ('BOE-A-2026-24883',40),('BOE-A-2026-24977',2)
) v(ref,vacancies)
where c.official_call_identifier=v.ref and c.official_call_identifier_authority='BOE'
and c.vacancies is null;

insert into opposition_worker_private.verified_publications
  (source_id, external_id, boe_reference, publication_type, evidence_url)
select source_id,external_id,prior_reference,publication_type,evidence_url
from opposition_worker_private.territorial_reviews
where decision='vinculada'
on conflict (source_id, external_id) do nothing;

-- The inbox trigger links the five verified publications to their existing calls.
-- Correct the canonical Canary URLs before future captures and public links use them.
update public.opposition_territorial_inbox i
set official_url=r.evidence_url, official_pdf_url=coalesce(r.official_pdf_url,i.official_pdf_url)
from opposition_worker_private.territorial_reviews r
where i.source_id=r.source_id and i.external_id=r.external_id
  and (r.decision='vinculada' or i.official_url is distinct from r.evidence_url);
